    lane: &Lane,
    workspace_root: &Path,
    logger: &RunLogger,
    config: &OrchestratorConfig,
) -> anyhow::Result<LaneResult> {
    let command = lanes::lane_command(lane, crate_name, workspace_root);
    let cmd_str = command.join(" ");

